<script setup lang="ts">
import { computed,onMounted,onUnmounted,ref,watch } from 'vue'
import type { SessionData } from '../features/auth/client'
import type { ProfileVersionData } from '../features/profiles/client'
import type { AssessmentData } from '../features/eligibility/client'
import type { PlanApi } from '../features/plans/client'
import { usePlansWorkspace } from '../features/plans/usePlans'
import PlanWorkspaceForm from '../features/plans/PlanWorkspaceForm.vue'
import PlanSchedule from '../features/plans/PlanSchedule.vue'
import PlanTaskList from '../features/plans/PlanTaskList.vue'
import RevisionPanel from '../features/plans/revisions/RevisionPanel.vue'
import NotificationsPanel from '../features/plans/notifications/NotificationsPanel.vue'
import type { NotificationApi } from '../features/plans/notifications/client'
const props=defineProps<{actor:SessionData|null;coreAllowed:boolean;profile:ProfileVersionData|null;profileEpoch:number;targets:AssessmentData[];api?:PlanApi;notificationApi?:NotificationApi}>()
const emit=defineEmits<{sessionExpired:[]}>()
const workspace=usePlansWorkspace({api:props.api},()=>emit('sessionExpired')),{state}=workspace
const revisionExpanded=ref(false)
const notificationsExpanded=ref(false)
const revisionCurrent=computed(()=>state.busy||state.dirty||state.conflict?null:state.current)
function revisionInvalidated(){void workspace.setProfile(null,props.profileEpoch)}
watch(()=>[props.actor,props.coreAllowed] as const,([actor,core])=>workspace.setAccess(actor,core),{immediate:true,flush:'sync'})
watch(()=>[props.profile,props.profileEpoch] as const,([profile,epoch])=>{void workspace.setProfile(profile,epoch)},{immediate:true,flush:'sync'})
watch(()=>[props.targets,state.profile] as const,([targets])=>{void workspace.setTargets(targets)},{immediate:true,flush:'sync'})
onMounted(()=>{if(props.actor&&props.coreAllowed)void workspace.refreshContext()})
onUnmounted(workspace.dispose)
function historyInput(event:Event){state.historyVersion=(event.target as HTMLInputElement).value;state.history=null}
</script>
<template><section class="plans-workspace" data-testid="plans-workspace" aria-labelledby="plans-title" :aria-busy="state.busy"><header><div><p class="kicker">PREPARATION · TIME · PROGRESS</p><h2 id="plans-title">把下一步，变成可核对的安排。</h2><p>来源、估时与可用时间逐项保留。本人确认和完成声明不会改变资格，也不会提交申请。</p></div><span class="tag">计划与进度</span></header>
 <p class="boundary"><strong>真实资料处理尚未开放。</strong> 合成验收资料明确显示 DEMO；官方期限仍未核验，不自动生成 23:59 或准确截止。</p>
 <p v-if="!actor||!coreAllowed" class="message">登录和核心用途有效后才能明确读取私人计划。准入变化时，选择、内容与确认状态即时清空。</p>
 <template v-else><button type="button" class="secondary" data-testid="plan-context-refresh" :disabled="state.busy" @click="workspace.refreshContext">重新检查计划入口</button><p v-if="state.context?.is_synthetic" class="demo">DEMO · 本人合成计划验收，不是真实招生建议。</p><p v-if="state.message" class="message" :class="{error:state.error!==null}" :role="state.error!==null?'alert':'status'" data-testid="plan-message">{{ state.message }}</p>
 <template v-if="state.context"><section class="selection"><h3>明确选择准备目标 · 最多 4 个</h3><p>在项目工作台点击“加入准备目标”。历史或未知来源仅能生成相应核验安排，不能当作当前资格。</p><p v-if="!state.profile" class="note">创建及写操作需先在画像页明确读取当前确认版；已有计划仍可明确读取。</p><p v-else class="note">当前确认画像第 {{ state.profile.version }} 版 · {{ state.profile.version_id }}</p><p v-if="!state.targets.length" class="note">尚未加入已返回的本人评估；不使用预填 UUID。</p><label v-for="target in state.targets" :key="target.assessment_id" class="check"><input type="checkbox" :data-testid="`plan-assessment-select-${target.assessment_id}`" :checked="state.selectedIds.includes(target.assessment_id)" :disabled="state.busy" @change="workspace.selectAssessment(target.assessment_id,($event.target as HTMLInputElement).checked)"><span>项目 {{ target.target.offering_id }} · {{ target.stage==='application'?'申请':'入学' }} · {{ target.current_validity==='current'&&target.eligibility.status!=='unknown'?target.eligibility.status:'仅核验来源' }}<small>评估 {{ target.assessment_id }} · 原发布 {{ target.release_id }}</small></span></label><label class="check"><input v-model="state.createConfirmed" type="checkbox" data-testid="plan-create-confirmation" :disabled="state.busy||!state.profile||!state.context.can_create||!state.selectedIds.length"><span>我明确选择这些准备目标并请求创建草案；这不是最终计划确认。</span></label><button type="button" class="primary" data-testid="plan-create" :disabled="state.busy||!state.profile||!state.context.can_create||!state.createConfirmed||!state.selectedIds.length||state.conflict||!!state.retryKind" @click="workspace.createPlan">创建准备草案</button></section>
 <section class="saved"><div class="section-heading"><h3>本人已保存计划</h3><button type="button" class="secondary" data-testid="plan-list" :disabled="state.busy||!workspace.canRead()" @click="workspace.listPlans()">明确读取列表</button></div><div v-if="state.page" class="plan-list"><button v-for="item in state.page.items" :key="item.plan_id" type="button" class="plan-row" :data-testid="`plan-load-${item.plan_id}`" :disabled="state.busy" @click="workspace.loadPlan(item.plan_id)"><span>{{ item.state==='confirmed'?'本人已确认':'未确认草案' }} · 状态 v{{ item.state_version }} · 完成 {{ item.completed_count }} 项</span><small>{{ item.plan_id }}</small></button><button v-if="state.page.next_cursor" type="button" class="secondary" data-testid="plan-next" :disabled="state.busy" @click="workspace.nextPage">下一页</button><p v-if="!state.page.items.length">尚无可读计划。</p></div></section>
 <div v-if="state.conflict" class="conflict" data-testid="plan-conflict"><strong>写入已锁定，结果未确认。</strong><p>旧来源或状态已变化。未提交参数保留供核对；不会自动覆盖、移动过去时段或再次写入。</p><details v-if="!state.current"><summary>核对未提交参数（只读，不能执行）</summary><label v-for="(value,key) in state.local.estimates" :key="key">任务 {{ key }} · 小时<input :value="value" :data-testid="`plan-estimate-${key}`" readonly></label><p>UTC 区间 {{ state.local.horizonStart||'未提供' }} → {{ state.local.horizonEnd||'未提供' }} · 每周 {{ state.local.weeklyHours===''?'未知':state.local.weeklyHours }} 小时</p></details><button type="button" class="secondary" data-testid="plan-reload-current" :disabled="state.busy||!state.planId||!workspace.canRead()" @click="workspace.reloadCurrent">明确读取当前版本并核对参数</button></div>
 <button v-if="state.retryKind==='confirm'" type="button" class="secondary" data-testid="plan-confirm-retry" :disabled="state.busy||!state.profile" @click="workspace.retryConfirm">明确重试原确认请求（同内容、同 key）</button><button v-if="state.retryKind==='complete'" type="button" class="secondary" data-testid="plan-complete-retry" :disabled="state.busy||!state.profile" @click="workspace.retryComplete">明确重试原完成声明（原 CAS）</button>
 <section v-if="state.current" class="current" data-testid="plan-current"><div class="section-heading"><h3>当前计划 · {{ state.current.state==='confirmed'?'本人已确认':'未确认草案' }}</h3><span data-testid="plan-current-state-version">{{ state.current.state_version }}</span></div><dl><div><dt>计划 ID</dt><dd>{{ state.current.plan_id }}</dd></div><div><dt>画像确认版</dt><dd>{{ state.current.proposal.effective_draft.profile_version_id }}</dd></div><div><dt>当前草案 SHA</dt><dd>{{ state.current.proposal.effective_draft.draft_sha256 }}</dd></div><div><dt>来源有效期</dt><dd>{{ state.current.expires_at }}</dd></div></dl><p v-if="!workspace.canWrite()" class="note">当前内容可核对；写操作仍须明确选择此计划对应的当前确认画像，以及有效服务端能力。</p>
  <PlanWorkspaceForm v-if="state.current.state==='draft'" :local="state.local" :current="state.current" :disabled="!workspace.canWrite()||!state.context.can_edit" @changed="workspace.changeLocal" @save="workspace.saveWorkspace" />
  <PlanSchedule :execution="state.current" />
  <div v-if="state.current.state==='draft'" class="final-confirm"><label class="check"><input v-model="state.confirmChecked" type="checkbox" data-testid="plan-confirm" :disabled="!workspace.canConfirm()"><span>我已核对服务端当前草案、容量方案与依赖，明确确认本人的计划。</span></label><label class="check"><input v-model="state.deadlineAcknowledged" type="checkbox" data-testid="plan-ack-unknown" :disabled="!workspace.canConfirm()"><span>我知道官方期限仍未核验；确认此安排不会把候选时间或资格变成官方事实。</span></label><button type="button" class="primary" data-testid="plan-submit-confirm" :disabled="!workspace.canConfirm()||!state.confirmChecked||!state.deadlineAcknowledged" @click="workspace.confirmPlan">明确确认此计划</button></div>
  <p v-else class="note">确认状态与 T30 原草案标记分开。此版本已冻结，不能编辑安排；完成仅本人声明。</p><PlanTaskList :execution="state.current" :confirmations="state.taskConfirmations" :can-complete="workspace.canComplete" @confirm="(key,value)=>state.taskConfirmations[key]=value" @complete="workspace.completeTask" />
 </section>
 <section v-if="state.planId" class="history"><h3>只读历史 · 与当前编辑分开</h3><div class="history-query"><label>明确状态版本<input :value="state.historyVersion" data-testid="plan-history-version" inputmode="numeric" autocomplete="off" @input="historyInput"></label><button type="button" class="secondary" data-testid="plan-history-load" :disabled="state.busy||!workspace.canRead()||!state.historyVersion" @click="workspace.readHistory()">读取此历史版本</button></div><div v-if="state.history" class="history-result" data-testid="plan-history-result"><p><strong>只读历史状态 v{{ state.history.state_version }}</strong> · {{ state.history.state==='confirmed'?'原本人确认':'原草案' }}</p><p>历史方案 {{ state.history.proposal.id }}；不使用历史 CAS 写入当前计划。</p><PlanSchedule :execution="state.history" /><PlanTaskList :execution="state.history" readonly /></div></section>
 </template><section class="history"><h3>画像或来源变化后的修订</h3><p class="note">已有新草案后，可明确读取旧计划历史并选择接受或拒绝。新草案仍须单独最终确认，旧完成仅保留为历史。</p><button type="button" class="secondary" data-testid="revision-toggle" :aria-expanded="revisionExpanded" @click="revisionExpanded=!revisionExpanded">{{ revisionExpanded?'收起修订审阅':'展开修订审阅' }}</button><RevisionPanel v-if="revisionExpanded" :actor="actor" :core-allowed="coreAllowed" :profile="profile" :profile-epoch="profileEpoch" :current="revisionCurrent" :plan-api="api" @private-invalidated="revisionInvalidated" @session-expired="emit('sessionExpired')" /></section><section class="history"><h3>站内变更提醒与本人偏好</h3><p class="note">仅提示原依据的变化，不是资格或录取结论。默认关闭偏好，不发送邮件或短信。</p><button type="button" class="secondary" data-testid="notifications-toggle" :aria-expanded="notificationsExpanded" @click="notificationsExpanded=!notificationsExpanded">{{ notificationsExpanded?'收起站内提醒':'展开站内提醒' }}</button><NotificationsPanel v-if="notificationsExpanded" :actor="actor" :core-allowed="coreAllowed" :profile="profile" :profile-epoch="profileEpoch" :api="notificationApi" @private-invalidated="revisionInvalidated" @session-expired="emit('sessionExpired')" /></section></template>
 </section></template>
<style scoped>
.plans-workspace{grid-column:1/-1;min-width:0;padding:30px;background:#fff;color:#294c3b;border:1px solid #dce6d6;border-radius:12px}.plans-workspace header{display:flex;justify-content:space-between;align-items:flex-start;gap:20px}.kicker{font-size:10px;letter-spacing:1.7px;color:#8a977b}h2{font-size:25px;line-height:1.5;margin:0}header p:last-child,.note,.selection p,.saved p,.history p{font-size:11px;line-height:1.9;color:#7b896f}.tag{white-space:nowrap;border:1px solid #dbe5cd;border-radius:20px;padding:8px 12px;font-size:10px;color:#7c8e6b}.boundary,.demo,.message,.conflict{padding:15px 18px;background:#f5f7eb;border:1px solid #dce5cd;border-radius:7px;font-size:11px;line-height:1.9;margin:20px 0;overflow-wrap:anywhere}.demo{background:#f9f3e5;color:#82703e}.message.error,.conflict{background:#fcf2e7;color:#8b653c;border-color:#e6d7be}h3{font-size:16px;margin:0 0 15px}.selection,.saved,.current,.history{border-top:1px solid #e0e8d7;padding-top:24px;margin-top:27px}.section-heading{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:15px}.section-heading h3{margin:0}.section-heading>span{font-size:12px;border:1px solid #d9e4d1;border-radius:6px;padding:5px 9px}.check{display:flex;gap:10px;align-items:flex-start;font-size:11px;line-height:1.9;margin:18px 0}.check input{width:17px;height:17px;flex:0 0 17px;margin:3px 0 0}.check span{min-width:0;overflow-wrap:anywhere}.check small{display:block;font-size:9px;color:#8b977e}.primary,.secondary{border:1px solid #baccb5;border-radius:6px;padding:11px 15px;font-size:11px;line-height:1.7;background:#fff;color:#426c47}.primary{background:#1b6453;color:white;border-color:#1b6453}button:disabled{background:#f0f3e9;color:#919c85;border-color:#e0e7d9}.plan-list{display:grid;gap:10px}.plan-row{display:flex;flex-direction:column;gap:8px;text-align:left;background:#f8faf4;color:#496b46;border:1px solid #dbe6d1;padding:14px 17px;border-radius:7px;font-size:11px}.plan-row small{font-size:9px;overflow-wrap:anywhere}.current dl{display:grid;gap:10px;font-size:10px}.current dl>div{display:grid;grid-template-columns:105px minmax(0,1fr);gap:12px}.current dt{color:#8d977f}.current dd{margin:0;line-height:1.9;overflow-wrap:anywhere}.final-confirm{padding:4px 19px 20px;border:1px solid #d9e5ce;border-radius:8px;background:#f8faf3;margin:20px 0}.history-query{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:15px;align-items:end}.history-query label{display:flex;flex-direction:column;gap:8px;font-size:11px}.history-query input{width:100%;min-width:0;border:1px solid #cad8c1;border-radius:6px;padding:11px;font-size:11px}.history-result{padding:18px;border:1px dashed #bbc6ae;background:#f6f6f1;margin-top:20px;border-radius:8px}.plans-workspace :focus-visible{outline:3px solid #8cb6a4;outline-offset:3px}@media(max-width:650px){.plans-workspace{padding:24px 17px}h2{font-size:22px}header,.section-heading{flex-wrap:wrap}.history-query{grid-template-columns:1fr}.current dl>div{grid-template-columns:1fr;gap:3px}.history-result{padding:15px 11px}}
</style>
